class FakeEcu:
    def __init__(self):
        self.session = 0x01
        self.dtcs = {0x012345: 0x2F, 0xC10087: 0x08}
    def handle(self, req):
        sid = req[0]
        if sid == 0x10:
            self.session = req[1]
            return bytes([0x50, req[1], 0x00, 0x32, 0x01, 0xF4])
        if sid == 0x11:
            self.session = 0x01
            return bytes([0x51, req[1]])
        if sid == 0x31:
            if self.session != 0x03:
                return bytes([0x7F, sid, 0x7F])
            return bytes([0x71]) + req[1:4] + b"\x00"
        if sid == 0x19 and req[1] == 0x02:
            out = bytes([0x59, 0x02, 0xFF])
            for code, st in self.dtcs.items():
                if st & req[2]:
                    out += code.to_bytes(3, "big") + bytes([st])
            return out
        return bytes([0x7F, sid, 0x11])

def check(name, ecu, req, expect):
    res = ecu.handle(bytes(req))
    print("PASS" if res.startswith(bytes(expect)) else "FAIL", name, "|", bytes(req).hex(" "), "->", res.hex(" "))

ecu = FakeEcu()
check("기본 세션에서 루틴 거절", ecu, [0x31, 0x01, 0xFF, 0x00], [0x7F, 0x31, 0x7F])
check("확장 세션 들어가기", ecu, [0x10, 0x03], [0x50, 0x03])
check("확장 세션에서 루틴 실행", ecu, [0x31, 0x01, 0xFF, 0x00], [0x71, 0x01, 0xFF, 0x00])
check("리셋", ecu, [0x11, 0x01], [0x51, 0x01])
check("리셋 뒤 루틴 다시 거절", ecu, [0x31, 0x01, 0xFF, 0x00], [0x7F, 0x31, 0x7F])
check("확정 고장 코드만 읽기", ecu, [0x19, 0x02, 0x08], [0x59, 0x02])
# PASS 기본 세션에서 루틴 거절 | 31 01 ff 00 -> 7f 31 7f
# PASS 확장 세션 들어가기 | 10 03 -> 50 03 00 32 01 f4
# PASS 확장 세션에서 루틴 실행 | 31 01 ff 00 -> 71 01 ff 00 00
# PASS 리셋 | 11 01 -> 51 01
# PASS 리셋 뒤 루틴 다시 거절 | 31 01 ff 00 -> 7f 31 7f
# PASS 확정 고장 코드만 읽기 | 19 02 08 -> 59 02 ff 01 23 45 2f c1 00 87 08
